  for(const r of rooms) for(let z=r.z;z<r.z+r.d;z++) for(let x=r.x;x<r.x+r.w;x++) g[z][x]='.';
  for(const c of corrs) for(let z=c.z;z<c.z+c.d;z++) for(let x=c.x;x<c.x+c.w;x++) g[z][x]='.';
  return g;
}
const L1={
 rooms:[
  {x:11,z:21,w:5,d:5}, // foyer
