for(const [name,L] of Object.entries({L1,L2,L3,L4})){
  const g=make(L.rooms,L.corrs);
  console.log('\n=== '+name+' ===');
  console.log(g.map(r=>r.join('')).join('\n'));
  // connectivity
  const start=name==='L1'?[13,23]:name==='L2'?[13,23]:name==='L3'?[13,23]:[13,23];
  const seen=new Set([start.join(',')]);const q=[start];
  while(q.length){const [x,z]=q.shift(); for(const [dx,dz] of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,nz=z+dz,k=nx+','+nz;if(nx>=0&&nx<W&&nz>=0&&nz<H&&g[nz][nx]==='.'&&!seen.has(k)){seen.add(k);q.push([nx,nz]);}}}
  let floors=0;for(const row of g)for(const c of row)if(c==='.')floors++;
  console.log('floors',floors,'reachable',seen.size,'start',start,'OK',floors===seen.size);
}
