.audio-pill { align-self: center; font-family: var(--font-mono); font-size: .5rem; letter-spacing: .15em; border: 1px solid var(--line); padding: .35rem .55rem; color: rgba(242,234,215,.5); }
.hover-tag {
  position: absolute; z-index: 24; transform: translate(-50%, -100%) translateY(-10px);
  display: flex; flex-direction: column; align-items: center; padding: .45rem .7rem .5rem;
  background: rgba(9, 11, 9, .86); border: 1px solid rgba(184,255,61,.28); backdrop-filter: blur(8px);
  pointer-events: none; white-space: nowrap;
}
.hover-tag::after { content: ""; position: absolute; bottom: -5px; width: 8px; height: 8px; background: inherit; border-right: 1px solid rgba(184,255,61,.28); border-bottom: 1px solid rgba(184,255,61,.28); transform: rotate(45deg); }
.hover-tag strong { font-family: var(--font-display); font-size: .7rem; letter-spacing: .05em; }
.hover-tag em { font-family: var(--font-mono); font-style: normal; font-size: .52rem; letter-spacing: .1em; color: rgba(242,234,215,.52); }
.hover-dot { position: absolute; top: -4px; right: -4px; width: 8px; height: 8px; background: var(--acid); border-radius: 50%; box-shadow: 0 0 8px var(--acid); }

.listing {
  position: absolute; right: calc(1.4rem + var(--safe-r)); top: 50%; transform: translateY(-50%);
  width: min(352px, calc(100vw - 2rem)); background: var(--panel); backdrop-filter: blur(18px);
  border: 1px solid rgba(242,234,215,.14); box-shadow: 0 35px 80px rgba(0,0,0,.55);
  pointer-events: auto; overflow: hidden;
  animation: listingIn .4s cubic-bezier(.2,.8,.2,1);
}
@keyframes listingIn { from { opacity: 0; transform: translateY(-48%) translateX(16px); } to { opacity: 1; transform: translateY(-50%) translateX(0); } }
.listing-stripe { height: 5px; background: linear-gradient(90deg, var(--acid), #3d8a2d 55%, transparent); }
.listing-body { padding: 1.15rem 1.25rem 1rem; }
.listing-kicker { display: flex; justify-content: space-between; align-items: center; font-family: var(--font-mono); font-size: .52rem; letter-spacing: .17em; color: rgba(242,234,215,.48); }
.listing-status { color: var(--acid); border: 1px solid rgba(184,255,61,.32); padding: .2rem .4rem; }
.listing-status.sold { color: var(--gold); border-color: rgba(255,209,102,.4); }
.listing h2 { margin: .55rem 0 .1rem; font-family: var(--font-display); font-size: 1.55rem; line-height: .98; letter-spacing: -.03em; text-transform: uppercase; }
.listing-addr { margin: 0; font-family: var(--font-mono); font-size: .6rem; letter-spacing: .13em; color: rgba(242,234,215,.55); text-transform: uppercase; }
.listing-rating { display: flex; align-items: center; gap: .7rem; margin-top: .65rem; }
.stars { color: var(--doom); font-size: .8rem; letter-spacing: .16em; }
.rating-label { font-family: var(--font-mono); font-size: .5rem; letter-spacing: .15em; color: var(--doom); }
.listing-desc { margin: .75rem 0 .85rem; font-size: .77rem; line-height: 1.5; color: rgba(242,234,215,.7); font-style: italic; }
.listing-facts { display: grid; grid-template-columns: repeat(3, 1fr); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); margin-bottom: .9rem; }
.listing-facts div { padding: .55rem 0 .5rem; border-right: 1px solid var(--line); }
.listing-facts div:last-child { border-right: 0; padding-left: .8rem; }
.listing-facts div:nth-child(2) { padding-left: .8rem; }
.listing-facts span { display: block; font-family: var(--font-mono); font-size: .46rem; letter-spacing: .14em; color: rgba(242,234,215,.42); margin-bottom: .15rem; }
.listing-facts strong { font-family: var(--font-display); font-size: 1rem; }
#enterBtn { width: 100%; padding: .9rem 1rem; }
.listing-foot { display: flex; align-items: center; justify-content: center; gap: .4rem; margin-top: .65rem; font-family: var(--font-mono); font-size: .5rem; letter-spacing: .06em; color: rgba(242,234,215,.4); }

.hub-footer {
  position: absolute; left: 0; right: 0; bottom: 0;
  padding: 0 calc(1.3rem + var(--safe-r)) calc(.9rem + var(--safe-b)) calc(1.3rem + var(--safe-l));
  display: flex; align-items: flex-end; justify-content: space-between; gap: 1rem;
}
.hub-tip { display: flex; align-items: center; gap: .5rem; font-family: var(--font-mono); font-size: .58rem; letter-spacing: .1em; color: rgba(242,234,215,.52); }
.hub-tip strong { color: var(--cream); }
.tip-gem { width: 9px; height: 14px; background: linear-gradient(150deg,#d6ff73,#3da132); clip-path: polygon(50% 0,100% 38%,50% 100%,0 38%); filter: drop-shadow(0 0 6px rgba(103,217,79,.6)); }
.hub-legal { font-family: var(--font-mono); font-size: .46rem; letter-spacing: .15em; color: rgba(242,234,215,.28); text-align: right; }

/* ---------- level hud ---------- */
#level-hud { position: absolute; inset: 0; z-index: 20; pointer-events: none; }
.level-top-left { position: absolute; top: calc(1rem + var(--safe-t)); left: calc(1.1rem + var(--safe-l)); width: min(300px, 42vw); }
.level-house { display: flex; gap: .6rem; align-items: center; margin-bottom: .65rem; }
.level-house > span { font-family: var(--font-display); font-size: 1.7rem; line-height: 1; color: transparent; -webkit-text-stroke: 1px rgba(242,234,215,.45); }
.level-house strong { display: block; font-family: var(--font-display); font-size: .86rem; letter-spacing: .02em; line-height: 1; }
.level-house em { display: block; font-family: var(--font-mono); font-style: normal; font-size: .48rem; letter-spacing: .16em; color: rgba(242,234,215,.48); margin-top: .22rem; }
.objective { border-left: 2px solid var(--acid); padding: .1rem 0 .1rem .55rem; background: linear-gradient(90deg, rgba(184,255,61,.09), transparent); }
.obj-label { font-family: var(--font-mono); font-size: .45rem; letter-spacing: .22em; color: var(--acid); margin-bottom: .15rem; }
#objText { font-family: var(--font-display); font-size: .68rem; letter-spacing: .02em; color: var(--cream); }
.obj-bar { height: 3px; background: rgba(242,234,215,.12); margin-top: .38rem; width: 100%; max-width: 190px; overflow: hidden; }
.obj-bar i { display: block; height: 100%; width: 0; background: var(--acid); transition: width .3s ease; box-shadow: 0 0 10px rgba(184,255,61,.5); }
.kill-line { display: flex; align-items: baseline; gap: .5rem; margin-top: .55rem; font-family: var(--font-mono); font-size: .5rem; letter-spacing: .12em; color: rgba(242,234,215,.46); }
.kill-line strong { color: rgba(242,234,215,.8); font-size: .6rem; }

.level-top-right { position: absolute; top: calc(1rem + var(--safe-t)); right: calc(1.1rem + var(--safe-r)); display: flex; flex-direction: column; align-items: flex-end; gap: .5rem; }
.minimap-wrap { position: relative; width: clamp(132px, 14vw, 180px); aspect-ratio: 1; background: rgba(5,7,5,.7); border: 1px solid rgba(242,234,215,.18); box-shadow: 0 10px 30px rgba(0,0,0,.4); }
#minimap { width: 100%; height: 100%; display: block; image-rendering: pixelated; }
.minimap-frame { position: absolute; inset: 0; pointer-events: none; background: linear-gradient(135deg, rgba(184,255,61,.2), transparent 25%), linear-gradient(-45deg, rgba(255,90,36,.15), transparent 30%); }
.waypoint { position: absolute; left: 50%; bottom: -1.6rem; transform: translateX(-50%); display: flex; align-items: center; gap: .3rem; font-family: var(--font-mono); font-size: .5rem; color: var(--cyan); letter-spacing: .08em; white-space: nowrap; text-shadow: 0 1px 4px #000; }
.waypoint span { display: inline-block; font-size: .55rem; transition: transform .1s linear; }
.level-timer { display: flex; align-items: baseline; gap: .45rem; font-family: var(--font-mono); font-size: .5rem; letter-spacing: .14em; color: rgba(242,234,215,.45); }
.level-timer strong { color: var(--cream); font-size: .74rem; letter-spacing: .06em; }

.hud-bottom {
  position: absolute; left: calc(1rem + var(--safe-l)); right: calc(1rem + var(--safe-r)); bottom: calc(.8rem + var(--safe-b));
  display: flex; align-items: flex-end; justify-content: space-between; gap: 1rem;
}
.hp-block { width: clamp(150px, 20vw, 230px); background: linear-gradient(180deg, rgba(8,10,8,.1), rgba(8,10,8,.78)); border-bottom: 2px solid rgba(184,255,61,.45); padding: .55rem .7rem .5rem; backdrop-filter: blur(6px); }
.hp-icon { display: none; }
.hp-meta { display: flex; align-items: baseline; justify-content: space-between; }
.hp-meta span { font-family: var(--font-mono); font-size: .46rem; letter-spacing: .2em; color: rgba(242,234,215,.5); }
.hp-meta strong { font-family: var(--font-display); font-size: 1.75rem; line-height: .9; color: var(--acid); }
.hp-bar { height: 5px; background: rgba(242,234,215,.12); margin: .3rem 0 .25rem; overflow: hidden; }
.hp-bar i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #5ddc46, var(--acid)); transition: width .2s ease; box-shadow: 0 0 10px rgba(184,255,61,.4); }
.hp-bar i.low { background: linear-gradient(90deg, #d61f1f, #ff6a2a); }
.armor-line { font-family: var(--font-mono); font-size: .48rem; letter-spacing: .1em; color: rgba(242,234,215,.45); }
.armor-line b { color: var(--cyan); }
.shield { color: var(--cyan); }

.sim-face-wrap { position: relative; width: 82px; height: 82px; flex: 0 0 auto; display: flex; align-items: center; justify-content: center; }
#simFace { width: 68px; height: 68px; image-rendering: pixelated; background: #0a0c0a; border: 1px solid rgba(242,234,215,.22); box-shadow: 0 0 25px rgba(184,255,61,.12); }
.sim-face-ring { position: absolute; inset: 0; border: 1px solid rgba(184,255,61,.2); transform: rotate(45deg) scale(.78); pointer-events: none; }
.sim-face-label { position: absolute; bottom: -2px; font-family: var(--font-mono); font-size: .4rem; letter-spacing: .16em; color: rgba(184,255,61,.65); background: #0a0c0a; padding: 0 .2rem; }

.ammo-block { text-align: right; background: linear-gradient(180deg, rgba(8,10,8,.1), rgba(8,10,8,.78)); border-bottom: 2px solid rgba(255,90,36,.45); padding: .5rem .7rem .45rem; backdrop-filter: blur(6px); min-width: 190px; }
.weapon-name { font-family: var(--font-mono); font-size: .48rem; letter-spacing: .2em; color: var(--doom); }
.ammo-readout { display: flex; align-items: baseline; justify-content: flex-end; gap: .25rem; }
.ammo-readout strong { font-family: var(--font-display); font-size: 2rem; line-height: .9; }
.ammo-readout span { font-family: var(--font-mono); font-size: .68rem; color: rgba(242,234,215,.5); }
.ammo-pips { display: flex; justify-content: flex-end; gap: 2px; margin: .25rem 0 .3rem; height: 5px; }
.ammo-pips i { width: 9px; height: 100%; background: var(--doom); opacity: .85; }
