.lock-hint {
  position: absolute; left: 50%; top: 54%; transform: translate(-50%,-50%);
  font-family: var(--font-mono); font-size: .58rem; letter-spacing: .16em; color: rgba(242,234,215,.72);
  background: rgba(5,7,5,.72); border: 1px solid rgba(242,234,215,.16); padding: .6rem .9rem;
  display: flex; align-items: center; gap: .55rem; backdrop-filter: blur(6px);
}
.mouse-icon { width: 12px; height: 17px; border: 1px solid rgba(242,234,215,.65); border-radius: 6px; position: relative; }
.mouse-icon::after { content: ""; position: absolute; top: 3px; left: 50%; transform: translateX(-50%); width: 1px; height: 4px; background: var(--acid); }
.level-subtitle {
  position: absolute; left: 50%; bottom: 24%; transform: translateX(-50%); max-width: min(600px, 82vw);
  font-family: var(--font-mono); font-size: .66rem; letter-spacing: .05em; line-height: 1.5; text-align: center;
  color: rgba(242,234,215,.9); text-shadow: 0 2px 8px #000; opacity: 0; transition: opacity .25s; pointer-events: none;
}
.level-subtitle.on { opacity: 1; }
.interact-prompt {
  position: absolute; left: 50%; bottom: 28%; transform: translateX(-50%);
  display: flex; align-items: center; gap: .55rem; font-family: var(--font-mono); font-size: .7rem; letter-spacing: .12em;
  background: rgba(5,7,5,.78); border: 1px solid rgba(184,255,61,.35); padding: .55rem .8rem; color: var(--acid);
  text-shadow: 0 0 8px rgba(184,255,61,.4); backdrop-filter: blur(6px);
}

/* ---------- crosshair ---------- */
#crosshair { position: absolute; left: 50%; top: 50%; width: 30px; height: 30px; transform: translate(-50%,-50%); z-index: 18; pointer-events: none; }
.ch-dot { position: absolute; left: 50%; top: 50%; width: 3px; height: 3px; transform: translate(-50%,-50%); background: var(--cream); border-radius: 50%; box-shadow: 0 0 4px #000; }
.ch-line { position: absolute; background: rgba(242,234,215,.78); box-shadow: 0 0 2px rgba(0,0,0,.8); transition: transform .09s ease; }
.ch-n, .ch-s { width: 1px; height: 7px; left: 50%; }
.ch-e, .ch-w { height: 1px; width: 7px; top: 50%; }
.ch-n { top: 1px; } .ch-s { bottom: 1px; } .ch-e { right: 1px; } .ch-w { left: 1px; }
#crosshair.hit .ch-line { background: #fff; box-shadow: 0 0 6px var(--doom); }
#crosshair.hit .ch-n { transform: translateY(-4px); } #crosshair.hit .ch-s { transform: translateY(4px); }
#crosshair.hit .ch-e { transform: translateX(4px); } #crosshair.hit .ch-w { transform: translateX(-4px); }
#crosshair.kill .ch-dot { background: var(--doom); }

/* ---------- touch ---------- */
#touch-controls { position: absolute; inset: 0; z-index: 22; pointer-events: none; }
.stick { position: absolute; left: calc(1.2rem + var(--safe-l)); bottom: calc(1.4rem + var(--safe-b)); width: 116px; height: 116px; border-radius: 50%; background: rgba(8,10,8,.3); border: 1px solid rgba(242,234,215,.2); pointer-events: auto; touch-action: none; }
.stick-ring { position: absolute; inset: 18px; border: 1px dashed rgba(242,234,215,.18); border-radius: 50%; }
.stick-knob { position: absolute; left: 50%; top: 50%; width: 42px; height: 42px; margin: -21px 0 0 -21px; border-radius: 50%; background: rgba(184,255,61,.22); border: 1px solid rgba(184,255,61,.55); box-shadow: 0 0 20px rgba(184,255,61,.12); }
.stick span { position: absolute; left: 50%; bottom: 6px; transform: translateX(-50%); font-family: var(--font-mono); font-size: .42rem; letter-spacing: .18em; color: rgba(242,234,215,.4); }
.touch-look-hint { position: absolute; right: 40%; top: 50%; transform: translateY(-50%); font-family: var(--font-mono); font-size: .48rem; letter-spacing: .2em; color: rgba(242,234,215,.3); pointer-events: none; }
.touch-actions { position: absolute; right: calc(1.1rem + var(--safe-r)); bottom: calc(1.2rem + var(--safe-b)); width: 150px; height: 150px; pointer-events: none; }
.touch-btn { position: absolute; pointer-events: auto; touch-action: none; border-radius: 50%; border: 1px solid rgba(242,234,215,.26); background: rgba(8,10,8,.42); font-family: var(--font-mono); font-size: .52rem; letter-spacing: .06em; backdrop-filter: blur(4px); }
.touch-btn:active { background: rgba(184,255,61,.22); border-color: var(--acid); }
.touch-fire { right: 0; bottom: 0; width: 82px; height: 82px; background: rgba(255,90,36,.18); border-color: rgba(255,90,36,.6); color: #ffb08e; font-family: var(--font-display); font-size: .72rem; }
.touch-small { width: 48px; height: 48px; }
#btnReload { right: 90px; bottom: 4px; } #btnSwitch { right: 58px; bottom: 68px; } #btnInteract { right: 0; bottom: 92px; border-color: rgba(184,255,61,.5); color: var(--acid); }

/* ---------- modals ---------- */
