.hp-bar i.low { background: linear-gradient(90deg, #d61f1f, #ff6a2a); }
.armor-line { font-family: var(--font-mono); font-size: .48rem; letter-spacing: .1em; color: rgba(242,234,215,.45); }
.armor-line b { color: var(--cyan); }
.shield { color: var(--cyan); }

.sim-face-wrap { position: relative; width: 82px; height: 82px; flex: 0 0 auto; display: flex; align-items: center; justify-content: center; }
#simFace { width: 68px; height: 68px; image-rendering: pixelated; background: #0a0c0a; border: 1px solid rgba(242,234,215,.22); box-shadow: 0 0 25px rgba(184,255,61,.12); }
.sim-face-ring { position: absolute; inset: 0; border: 1px solid rgba(184,255,61,.2); transform: rotate(45deg) scale(.78); pointer-events: none; }
.sim-face-label { position: absolute; bottom: -2px; font-family: var(--font-mono); font-size: .4rem; letter-spacing: .16em; color: rgba(184,255,61,.65); background: #0a0c0a; padding: 0 .2rem; }

.ammo-block { text-align: right; background: linear-gradient(180deg, rgba(8,10,8,.1), rgba(8,10,8,.78)); border-bottom: 2px solid rgba(255,90,36,.45); padding: .5rem .7rem .45rem; backdrop-filter: blur(6px); min-width: 190px; }
.weapon-name { font-family: var(--font-mono); font-size: .48rem; letter-spacing: .2em; color: var(--doom); }
.ammo-readout { display: flex; align-items: baseline; justify-content: flex-end; gap: .25rem; }
.ammo-readout strong { font-family: var(--font-display); font-size: 2rem; line-height: .9; }
.ammo-readout span { font-family: var(--font-mono); font-size: .68rem; color: rgba(242,234,215,.5); }
.ammo-pips { display: flex; justify-content: flex-end; gap: 2px; margin: .25rem 0 .3rem; height: 5px; }
.ammo-pips i { width: 9px; height: 100%; background: var(--doom); opacity: .85; }
.ammo-pips i.empty { background: rgba(242,234,215,.16); }
.weapon-keys { display: flex; align-items: center; justify-content: flex-end; gap: .25rem; font-family: var(--font-mono); font-size: .42rem; letter-spacing: .06em; color: rgba(242,234,215,.38); }

.souls-block { width: clamp(130px, 17vw, 190px); text-align: right; background: linear-gradient(180deg, rgba(8,10,8,.1), rgba(8,10,8,.78)); border-bottom: 2px solid rgba(87,230,255,.45); padding: .5rem .7rem .45rem; backdrop-filter: blur(6px); }
.souls-label { font-family: var(--font-mono); font-size: .46rem; letter-spacing: .2em; color: rgba(242,234,215,.5); }
.soul-slots { display: flex; justify-content: flex-end; gap: .35rem; margin: .3rem 0 .25rem; }
.soul-slot { width: 15px; height: 23px; display: inline-block; background: rgba(87,230,255,.07); border: 1px solid rgba(87,230,255,.26); clip-path: polygon(50% 0,100% 38%,50% 100%,0 38%); transition: background .3s, box-shadow .3s; }
.soul-slot.filled { background: linear-gradient(150deg,#c7f9ff,#3cc8e8 55%,#117a94); border-color: transparent; box-shadow: 0 0 12px rgba(87,230,255,.65); }
.souls-status { font-family: var(--font-mono); font-size: .46rem; letter-spacing: .12em; color: rgba(242,234,215,.42); }
.souls-status.open { color: var(--acid); text-shadow: 0 0 10px rgba(184,255,61,.5); }

.lock-hint {
  position: absolute; left: 50%; top: 54%; transform: translate(-50%,-50%);
  font-family: var(--font-mono); font-size: .58rem; letter-spacing: .16em; color: rgba(242,234,215,.72);
  background: rgba(5,7,5,.72); border: 1px solid rgba(242,234,215,.16); padding: .6rem .9rem;
  display: flex; align-items: center; gap: .55rem; backdrop-filter: blur(6px);
}
.mouse-icon { width: 12px; height: 17px; border: 1px solid rgba(242,234,215,.65); border-radius: 6px; position: relative; }
.mouse-icon::after { content: ""; position: absolute; top: 3px; left: 50%; transform: translateX(-50%); width: 1px; height: 4px; background: var(--acid); }
.level-subtitle {
  position: absolute; left: 50%; bottom: 24%; transform: translateX(-50%); max-width: min(600px, 82vw);
  font-family: var(--font-mono); font-size: .66rem; letter-spacing: .05em; line-height: 1.5; text-align: center;
  color: rgba(242,234,215,.9); text-shadow: 0 2px 8px #000; opacity: 0; transition: opacity .25s; pointer-events: none;
}
.level-subtitle.on { opacity: 1; }
.interact-prompt {
  position: absolute; left: 50%; bottom: 28%; transform: translateX(-50%);
  display: flex; align-items: center; gap: .55rem; font-family: var(--font-mono); font-size: .7rem; letter-spacing: .12em;
  background: rgba(5,7,5,.78); border: 1px solid rgba(184,255,61,.35); padding: .55rem .8rem; color: var(--acid);
  text-shadow: 0 0 8px rgba(184,255,61,.4); backdrop-filter: blur(6px);
}

/* ---------- crosshair ---------- */
#crosshair { position: absolute; left: 50%; top: 50%; width: 30px; height: 30px; transform: translate(-50%,-50%); z-index: 18; pointer-events: none; }
.ch-dot { position: absolute; left: 50%; top: 50%; width: 3px; height: 3px; transform: translate(-50%,-50%); background: var(--cream); border-radius: 50%; box-shadow: 0 0 4px #000; }
.ch-line { position: absolute; background: rgba(242,234,215,.78); box-shadow: 0 0 2px rgba(0,0,0,.8); transition: transform .09s ease; }
.ch-n, .ch-s { width: 1px; height: 7px; left: 50%; }
.ch-e, .ch-w { height: 1px; width: 7px; top: 50%; }
.ch-n { top: 1px; } .ch-s { bottom: 1px; } .ch-e { right: 1px; } .ch-w { left: 1px; }
#crosshair.hit .ch-line { background: #fff; box-shadow: 0 0 6px var(--doom); }
#crosshair.hit .ch-n { transform: translateY(-4px); } #crosshair.hit .ch-s { transform: translateY(4px); }
#crosshair.hit .ch-e { transform: translateX(4px); } #crosshair.hit .ch-w { transform: translateX(-4px); }
#crosshair.kill .ch-dot { background: var(--doom); }

/* ---------- touch ---------- */
#touch-controls { position: absolute; inset: 0; z-index: 22; pointer-events: none; }
.stick { position: absolute; left: calc(1.2rem + var(--safe-l)); bottom: calc(1.4rem + var(--safe-b)); width: 116px; height: 116px; border-radius: 50%; background: rgba(8,10,8,.3); border: 1px solid rgba(242,234,215,.2); pointer-events: auto; touch-action: none; }
.stick-ring { position: absolute; inset: 18px; border: 1px dashed rgba(242,234,215,.18); border-radius: 50%; }
.stick-knob { position: absolute; left: 50%; top: 50%; width: 42px; height: 42px; margin: -21px 0 0 -21px; border-radius: 50%; background: rgba(184,255,61,.22); border: 1px solid rgba(184,255,61,.55); box-shadow: 0 0 20px rgba(184,255,61,.12); }
.stick span { position: absolute; left: 50%; bottom: 6px; transform: translateX(-50%); font-family: var(--font-mono); font-size: .42rem; letter-spacing: .18em; color: rgba(242,234,215,.4); }
.touch-look-hint { position: absolute; right: 40%; top: 50%; transform: translateY(-50%); font-family: var(--font-mono); font-size: .48rem; letter-spacing: .2em; color: rgba(242,234,215,.3); pointer-events: none; }
.touch-actions { position: absolute; right: calc(1.1rem + var(--safe-r)); bottom: calc(1.2rem + var(--safe-b)); width: 150px; height: 150px; pointer-events: none; }
.touch-btn { position: absolute; pointer-events: auto; touch-action: none; border-radius: 50%; border: 1px solid rgba(242,234,215,.26); background: rgba(8,10,8,.42); font-family: var(--font-mono); font-size: .52rem; letter-spacing: .06em; backdrop-filter: blur(4px); }
.touch-btn:active { background: rgba(184,255,61,.22); border-color: var(--acid); }
.touch-fire { right: 0; bottom: 0; width: 82px; height: 82px; background: rgba(255,90,36,.18); border-color: rgba(255,90,36,.6); color: #ffb08e; font-family: var(--font-display); font-size: .72rem; }
.touch-small { width: 48px; height: 48px; }
#btnReload { right: 90px; bottom: 4px; } #btnSwitch { right: 58px; bottom: 68px; } #btnInteract { right: 0; bottom: 92px; border-color: rgba(184,255,61,.5); color: var(--acid); }

/* ---------- modals ---------- */
.screen-dim { background: rgba(4,5,4,.72); backdrop-filter: blur(8px); z-index: 55; }
.mute-btn {
  position: absolute; right: calc(.8rem + var(--safe-r)); bottom: calc(.8rem + var(--safe-b)); z-index: 62;
  width: 34px; height: 34px; border-radius: 50%; border: 1px solid var(--line); background: rgba(8,10,8,.6);
  font-size: .8rem; cursor: pointer; color: rgba(242,234,215,.7); backdrop-filter: blur(6px);
}
.mute-btn .mute-off { display: none; }
.mute-btn.muted .mute-on { display: none; }
.mute-btn.muted .mute-off { display: inline; color: var(--doom); }
.mute-btn:hover { border-color: rgba(242,234,215,.45); }
.rotate-note { display: none; }

/* ---------- responsive ---------- */
@media (max-width: 900px) {
  .hub-legal { display: none; }
  .hub-tip { font-size: .5rem; }
  .hub-right { gap: .8rem; }
  .hub-stat strong { font-size: 1.05rem; }
  .audio-pill { display: none; }
  .listing { width: min(320px, calc(100vw - 1.5rem)); }
  .level-top-left { width: 44vw; }
  .level-top-right { gap: .35rem; }
  .sim-face-wrap { display: none; }
  .weapon-keys { display: none; }
  .ammo-block { min-width: 130px; }
  .souls-block { width: 110px; }
  .hp-block { width: 140px; }
  .hud-bottom { gap: .5rem; }
  .level-house em { display: none; }
  .level-timer { font-size: .42rem; }
}
@media (max-width: 620px) {
  .intro-content { margin: 0 auto; align-items: center; text-align: center; }
  .logo-plumbob { position: relative; left: auto; top: auto; margin: 0 auto .6rem; }
  .intro-logo { display: flex; flex-direction: column; align-items: center; }
  .logo-rule { justify-content: center; }
  .intro-controls { justify-content: center; }
  .intro-agent { text-align: left; }
  .intro-copy { text-align: center; }
  .listing { top: auto; bottom: calc(4.2rem + var(--safe-b)); transform: none; right: .75rem; left: .75rem; width: auto; animation: listingUp .35s ease; }
  @keyframes listingUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
  .listing-body { padding: .9rem 1rem .8rem; }
  .listing h2 { font-size: 1.25rem; }
  .listing-desc { display: none; }
  .listing-facts { margin-bottom: .6rem; }
  .hub-footer { bottom: calc(2.8rem + var(--safe-b)); justify-content: center; }
  .hub-legal { display: none; }
  .level-top-left { width: 54vw; }
  .minimap-wrap { width: 108px; }
  .level-house > span { font-size: 1.2rem; }
  .level-house strong { font-size: .66rem; }
  #objText { font-size: .56rem; }
  .objective { padding-left: .4rem; }
  .kill-line { font-size: .42rem; }
  .hud-bottom { align-items: flex-end; bottom: calc(6.4rem + var(--safe-b)); left: .6rem; right: .6rem; }
  .hp-block { width: 30vw; padding: .4rem .5rem; }
  .hp-meta strong { font-size: 1.3rem; }
  .ammo-block { min-width: 0; width: 31vw; padding: .4rem .5rem; }
  .ammo-readout strong { font-size: 1.4rem; }
  .souls-block { width: 26vw; padding: .4rem .5rem; }
  .souls-label { font-size: .38rem; }
  .soul-slot { width: 11px; height: 17px; }
  .weapon-name { font-size: .4rem; }
  .level-subtitle { bottom: 29%; font-size: .56rem; }
  .interact-prompt { bottom: 33%; }
  .mute-btn { bottom: calc(.6rem + var(--safe-b)); }
  #toasts { top: calc(13% + var(--safe-t)); }
  .rotate-note { display: none; }
}

/* touch devices */
body.touch #lockHint { display: none; }
body.touch .weapon-keys { display: none; }
body.touch #touch-controls { display: block; }
body.touch .hud-bottom { bottom: calc(.7rem + var(--safe-b)); left: calc(1rem + var(--safe-l)); right: calc(1rem + var(--safe-r)); }
body.touch .souls-block { margin-right: 160px; }
body.touch .ammo-block { display: none; }
body.touch .hp-block { width: 130px; }
body.touch .sim-face-wrap { display: none; }
body.touch .level-subtitle { bottom: 36%; }
body.touch .interact-prompt { bottom: 42%; }
@media (max-width: 900px) {
  body.touch .hud-bottom { bottom: calc(8.6rem + var(--safe-b)); left: .7rem; right: .7rem; }
  body.touch .level-top-right .minimap-wrap { width: 92px; }
  body.touch .souls-block { margin-right: 0; width: 26vw; }
  body.touch .hp-block { width: 30vw; }
  body.touch .level-top-left { top: calc(.5rem + var(--safe-t)); left: .7rem; }
  body.touch .level-top-right { top: calc(.5rem + var(--safe-t)); right: .7rem; }
  body.touch .crosshair { opacity: .6; }
}
@media (orientation: portrait) and (max-width: 600px) {
  .rotate-note { display: block; position: absolute; left: 50%; bottom: calc(.6rem + var(--safe-b)); transform: translateX(-50%); font-family: var(--font-mono); font-size: .38rem; letter-spacing: .16em; color: rgba(242,234,215,.28); z-index: 15; pointer-events: none; }
}

}
#vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 4;
  background: radial-gradient(ellipse at center, transparent 52%, rgba(0, 0, 0, .34) 100%);
}
#damageFlash {
  position: absolute; inset: 0; pointer-events: none; z-index: 30; opacity: 0;
  background: radial-gradient(ellipse at center, transparent 35%, rgba(190, 8, 16, .65) 100%);
  transition: opacity .12s ease;
}
#damageFlash.on { opacity: 1; transition: none; }

/* ---------- shared bits ---------- */
.key-chip {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 1.5em; height: 1.5em; padding: 0 .38em;
  border: 1px solid rgba(242, 234, 215, .3); border-bottom-width: 2px; border-radius: 4px;
  background: rgba(242, 234, 215, .08);
  font-family: var(--font-mono); font-size: .66rem; letter-spacing: .04em; color: var(--cream);
}
.btn {
  display: inline-flex; flex-direction: column; align-items: center; justify-content: center; gap: .2rem;
  border: 0; border-radius: 2px; cursor: pointer; padding: .9rem 1.5rem;
  font-family: var(--font-display); font-size: .92rem; letter-spacing: .08em; line-height: 1;
  transition: transform .14s ease, background .14s ease, color .14s ease, box-shadow .14s ease;
  position: relative;
}
.btn small { font-family: var(--font-mono); font-size: .58rem; font-weight: 400; letter-spacing: .1em; opacity: .62; }
.btn-primary {
  color: #10140d; background: var(--acid);
  box-shadow: 0 0 0 1px rgba(184, 255, 61, .3), 0 12px 30px rgba(140, 255, 32, .12);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%);
}
.btn-primary:hover { background: #d3ff7c; transform: translateY(-2px); box-shadow: 0 0 0 1px rgba(184,255,61,.5), 0 18px 42px rgba(140,255,32,.22); }
.btn-primary:active { transform: translateY(0); }
.btn-ghost {
  background: transparent; border: 1px solid rgba(242, 234, 215, .24); color: var(--cream-dim);
  font-family: var(--font-mono); font-size: .72rem; letter-spacing: .14em; padding: .8rem 1.2rem;
}
.btn-ghost:hover { border-color: rgba(242, 234, 215, .6); color: var(--cream); background: rgba(242, 234, 215, .06); }

